// Merged schema.
// Ref: #/components/schemas/MigrationRun
type MigrationRun struct {
	// Identifier (UUIDv7).
	ID uuid.UUID `json:"id"`
	// Optimistic-lock version; equals the ETag. Increases by one on every change.
	Version int32 `json:"version"`
	// Creation time (UTC).
	CreatedAt time.Time `json:"created_at"`
	// Principal that created the resource.
	CreatedBy uuid.UUID `json:"created_by"`
	// Time of the last change (UTC).
	UpdatedAt time.Time `json:"updated_at"`
	// Principal that made the last change. Absent on resources whose table does not record it.
	UpdatedBy OptUUID `json:"updated_by"`
	// Source connector.
	ConnectorID uuid.UUID `json:"connector_id"`
	// The source connector's `name`, as it is now.
	ConnectorName string `json:"connector_name"`
	// Scope.
	Scope MigrationScope `json:"scope"`
	// Migrate open documents or balances only. Open enumeration: clients must accept and preserve values
	// not listed here; values may be added within /v1.
	Mode string `json:"mode"`
	// Rehearsal runs are discarded after reconciliation.
	IsRehearsal bool `json:"is_rehearsal"`
	// Lifecycle status. Open enumeration: clients must accept and preserve values not listed here; values
	// may be added within /v1.
	Status string `json:"status"`
	// What the run extracted, checked, loaded and reconciled (docs/migration.md); absent while the run is
	// queued and has not finished a step.
	Report OptMigrationRunReport `json:"report"`
	// Current or last operation.
	OperationID OptUUID `json:"operation_id"`
	// Start time.
	StartedAt OptDateTime `json:"started_at"`
	// End time.
	FinishedAt OptDateTime `json:"finished_at"`
}

